//! The nine cross-language spec-vector assertions.
//!
//! The corpus -- DAGs, partials, transmission packets, batched packets, broken
//! DAGs and the input trees they were built from -- is generated by the Go repo's
//! `tools/specvectors` and COMMITTED into this repository under `spec/vectors`.
//! Go, Swift and Rust each run these same nine assertions against their own copy.
//!
//! It is committed rather than resolved from a sibling checkout because the Swift
//! port tried that: its spec tests skipped silently on every machine without a Go
//! checkout next door, which was every machine, and reported green for four
//! releases while checking nothing. A missing corpus panics here.
//!
//! Every artifact is committed TWICE, once as `.cbor` and once as `.json` at the
//! same path. That is newer than the rest of the corpus and it exists because
//! this crate is where the CBOR-only gap bit -- see
//! `spec_vector_json_matches_the_committed_bytes`.
//!
//! The manifest itself is still read as CBOR rather than JSON. That used to be a
//! necessity -- the crate had no JSON parser to read it with -- and it is now a
//! choice: the manifest decides WHICH vectors get checked, so reading it with the
//! parser under test would let one bug hide another.

mod support;

use scionic_merkletree::encoding::{cbor_decode, CborValue};
use scionic_merkletree::{
    create_dag_with_options, BatchedDagReceiver, BatchedTransmissionPacket, Dag, LeafType,
    Metadata, TransmissionPacket, TransmissionReceiver,
};
use std::path::{Path, PathBuf};
use support::options_4096;

fn vectors_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("spec")
        .join("vectors")
}

fn vector_path(relative: &str) -> PathBuf {
    let mut path = vectors_root();
    for segment in relative.split('/') {
        path.push(segment);
    }
    path
}

fn read_vector(relative: &str) -> Vec<u8> {
    let path = vector_path(relative);
    std::fs::read(&path).unwrap_or_else(|error| {
        panic!(
            "spec vector missing at {}: {error}\n\
             Regenerate the corpus from the Go repo with:\n  \
             go run ./tools/specvectors -out ../Scionic-MerkleTree-Rust/spec/vectors"
,
            path.display()
        )
    })
}

fn manifest() -> CborValue {
    let decoded = cbor_decode(&read_vector("manifest.cbor")).expect("manifest.cbor does not decode");
    assert_eq!(
        number(field(&decoded, "chunk_size")),
        4096,
        "the corpus was generated at a different chunk size than options_4096 builds with"
    );
    decoded
}

fn cases(manifest: &CborValue) -> &[CborValue] {
    let cases = items(field(manifest, "cases"));
    assert!(
        !cases.is_empty(),
        "the manifest lists no cases; every assertion below would pass vacuously"
    );
    cases
}

/// `CborValue` is `#[non_exhaustive]`, so every match here carries a wildcard arm.
/// That is deliberate: this file is a downstream consumer of the public enum, and
/// it should keep compiling when a new representation variant is added.
fn field<'a>(value: &'a CborValue, key: &str) -> &'a CborValue {
    match value {
        CborValue::Map(pairs) => pairs
            .iter()
            .find(|(name, _)| name == key)
            .map(|(_, entry)| entry)
            .unwrap_or_else(|| panic!("manifest map has no `{key}` field")),
        _ => panic!("expected a CBOR map when reading `{key}`"),
    }
}

fn text(value: &CborValue) -> &str {
    match value {
        CborValue::Text(text) => text,
        _ => panic!("expected CBOR text"),
    }
}

fn number(value: &CborValue) -> usize {
    match value {
        CborValue::Unsigned(number) => *number as usize,
        _ => panic!("expected a CBOR unsigned integer"),
    }
}

fn items(value: &CborValue) -> &[CborValue] {
    match value {
        CborValue::Array(values) => values,
        _ => panic!("expected a CBOR array"),
    }
}

fn paths(case: &CborValue, key: &str) -> Vec<String> {
    items(field(case, key))
        .iter()
        .map(|entry| text(entry).to_owned())
        .collect()
}

/// The root metadata a case was BUILT with, as sorted key/value entries.
///
/// It is a list rather than a map in the manifest because the manifest's own CBOR
/// encoder does not sort map keys, and a manifest that cannot reproduce its own
/// bytes would undermine every byte comparison below it.
fn root_metadata(case: &CborValue) -> Metadata {
    items(field(case, "additional_data"))
        .iter()
        .map(|entry| {
            (
                text(field(entry, "key")).to_owned(),
                text(field(entry, "value")).to_owned(),
            )
        })
        .collect()
}

/// Byte-offset search, so the probe assertions can talk about both encodings with
/// one helper. `str::find` is not an option here: CBOR is not UTF-8.
fn find_bytes(haystack: &[u8], needle: &[u8]) -> usize {
    haystack
        .windows(needle.len())
        .position(|window| window == needle)
        .unwrap_or_else(|| {
            panic!(
                "{} is missing from the vector",
                String::from_utf8_lossy(needle)
            )
        })
}

fn assert_shape(label: &str, dag: &Dag, case: &CborValue) {
    assert_eq!(
        dag.root().as_str(),
        text(field(case, "root_hash")),
        "{label}: root CID"
    );
    assert_eq!(
        dag.len(),
        number(field(case, "leaf_count")),
        "{label}: leaf count"
    );

    let (mut files, mut directories, mut chunks) = (0usize, 0usize, 0usize);
    for leaf in dag.leaves().values() {
        let leaf_type = leaf.leaf_type();
        if leaf_type == LeafType::File {
            files += 1;
        } else if leaf_type == LeafType::Directory {
            directories += 1;
        } else if leaf_type == LeafType::Chunk {
            chunks += 1;
        }
    }
    assert_eq!(files, number(field(case, "file_leaves")), "{label}: file leaves");
    assert_eq!(
        directories,
        number(field(case, "directory_leaves")),
        "{label}: directory leaves"
    );
    assert_eq!(
        chunks,
        number(field(case, "chunk_leaves")),
        "{label}: chunk leaves"
    );
}

#[test]
fn spec_vector_full_dags_parse_and_verify() {
    let manifest = manifest();
    for case in cases(&manifest) {
        let name = text(field(case, "name"));
        let dag = Dag::from_cbor(&read_vector(text(field(case, "full_dag"))))
            .unwrap_or_else(|error| panic!("{name}: full DAG does not decode: {error:?}"));
        assert_shape(name, &dag, case);
        dag.verify()
            .unwrap_or_else(|error| panic!("{name}: full DAG does not verify: {error:?}"));
    }
}

/// Encoding the same DAG twice must produce the same bytes.
///
/// Not a theoretical property: Go's default CBOR encoder sorted nothing, so its
/// maps encoded in Go's randomized iteration order and generating this corpus
/// three times produced three different `dag.cbor` files for identical input.
/// Nothing was corrupted -- a CID comes from leaf fields, not from this envelope,
/// and CBOR maps are unordered to any decoder -- but it made the serialized form
/// unusable as an identity: not diffable, not cacheable, not dedupable.
///
/// Rust keeps leaves in a `BTreeMap`, so it is ordered by construction. This test
/// is what makes that a guarantee instead of an accident of the chosen container.
///
/// It also asserts the stronger property: the re-encoded bytes equal the COMMITTED
/// bytes, which Go produced. Determinism within a port only buys mutual
/// decodability; this buys byte-for-byte interoperability, and it is the assertion
/// that would catch either port drifting from RFC 8949 core-deterministic map
/// ordering.
#[test]
fn spec_vector_full_dag_cbor_is_deterministic() {
    let manifest = manifest();
    for case in cases(&manifest) {
        let name = text(field(case, "name"));
        let committed = read_vector(text(field(case, "full_dag")));
        let dag = Dag::from_cbor(&committed).unwrap();

        let first = dag.to_cbor().unwrap();
        let second = dag.to_cbor().unwrap();
        assert_eq!(
            first, second,
            "{name}: encoding the same DAG twice produced different bytes"
        );
        assert_eq!(
            first, committed,
            "{name}: re-encoded DAG differs from the bytes Go committed"
        );

        let round_tripped = Dag::from_cbor(&first)
            .unwrap_or_else(|error| panic!("{name}: re-encoded DAG does not decode: {error:?}"));
        assert_shape(&format!("{name} (round trip)"), &round_tripped, case);
        round_tripped.verify().unwrap();
    }
}

/// The only assertion here that exercises DAG construction rather than decoding:
/// rebuild each DAG from the committed input tree and require the same root CID.
/// This is what makes the corpus a spec rather than a snapshot -- a port can only
/// pass by chunking, naming, sorting and hashing exactly the way Go does.
#[test]
fn spec_vector_input_roots_rebuild_identically() {
    let manifest = manifest();
    for case in cases(&manifest) {
        let name = text(field(case, "name"));
        let input = vector_path(&format!(
            "cases/{name}/{}",
            text(field(case, "root_input_path"))
        ));
        // Additional data is part of the root CID preimage, so a rebuild that
        // ignores it lands on a different root. Empty metadata is the default,
        // and only json_metadata_probe carries anything here.
        let options = options_4096().with_root_metadata(root_metadata(case));
        let rebuilt = create_dag_with_options(&input, &options)
            .unwrap_or_else(|error| panic!("{name}: could not rebuild from input: {error:?}"));
        assert_shape(&format!("{name} (rebuilt)"), &rebuilt, case);
        rebuilt.verify().unwrap();
    }
}

#[test]
fn spec_vector_partial_dags_parse_and_verify() {
    let manifest = manifest();
    let mut checked = 0;
    let mut genuinely_partial = 0;
    for case in cases(&manifest) {
        let name = text(field(case, "name"));
        let root_hash = text(field(case, "root_hash"));
        for partial_path in paths(case, "partial_dags") {
            let partial = Dag::from_cbor(&read_vector(&partial_path)).unwrap_or_else(|error| {
                panic!("{name}: partial {partial_path} does not decode: {error:?}")
            });
            assert_eq!(partial.root().as_str(), root_hash, "{name}: {partial_path} root");
            partial.verify().unwrap_or_else(|error| {
                panic!("{name}: partial {partial_path} does not verify: {error:?}")
            });
            checked += 1;
            if partial.is_partial() {
                genuinely_partial += 1;
            }
        }
    }
    assert!(checked > 0, "no partial vectors in the corpus");
    // Not every partial vector is partial: single_small_file holds exactly one
    // file, so requesting it returns the whole DAG and `is_partial()` is correctly
    // false. What must hold is that SOME vector takes the proof-carrying path,
    // otherwise this test is re-testing full-DAG verification under another name.
    assert!(
        genuinely_partial > 0,
        "no vector in the corpus verifies through the partial-DAG proof path"
    );
}

/// Pins the half of the contract the positive vectors cannot: a port that accepted
/// everything would pass every other test in this file.
///
/// The assertion is deliberately "decode or verify must fail", not "the error
/// message contains X". Each port has its own error vocabulary, and requiring a
/// shared substring would assert that three independent enums agree on wording --
/// a requirement no user has, and one satisfiable by editing a string.
#[test]
fn spec_vector_negative_vectors_are_rejected() {
    let manifest = manifest();
    let mut checked = 0;
    for case in cases(&manifest) {
        let name = text(field(case, "name"));
        for negative in items(field(case, "negative_vectors")) {
            let kind = text(field(negative, "kind"));
            let description = text(field(negative, "description"));
            // Both encodings of the same broken DAG must be rejected. Checking
            // only CBOR would leave room for a lenient JSON path -- and the JSON
            // path is the one that went four releases with no cross-port test at
            // all.
            let cbor_rejected = match Dag::from_cbor(&read_vector(text(field(negative, "path")))) {
                Err(_) => true,
                Ok(broken) => broken.verify().is_err(),
            };
            assert!(
                cbor_rejected,
                "{name}: negative vector {kind:?} was accepted as CBOR ({description})"
            );
            let json_rejected =
                match Dag::from_json(&read_vector(text(field(negative, "path_json")))) {
                    Err(_) => true,
                    Ok(broken) => broken.verify().is_err(),
                };
            assert!(
                json_rejected,
                "{name}: negative vector {kind:?} was accepted as JSON ({description})"
            );
            checked += 2;
        }
    }
    assert!(
        checked > 0,
        "no negative vectors in the corpus; the positive vectors alone cannot show anything is rejected"
    );
}

#[test]
fn spec_vector_transmission_packets_replay() {
    let manifest = manifest();
    for case in cases(&manifest) {
        let name = text(field(case, "name"));
        let mut receiver = TransmissionReceiver::new();

        for packet_path in paths(case, "transmission_packets") {
            let committed = read_vector(&packet_path);
            let packet = TransmissionPacket::from_cbor(&committed)
                .unwrap_or_else(|error| panic!("{name}: {packet_path} does not decode: {error:?}"));

            let first = packet.to_cbor().unwrap();
            let second = packet.to_cbor().unwrap();
            assert_eq!(
                first, second,
                "{name}: encoding {packet_path} twice produced different bytes"
            );
            assert_eq!(
                first, committed,
                "{name}: re-encoded {packet_path} differs from the bytes Go committed"
            );

            let round_tripped = TransmissionPacket::from_cbor(&first).unwrap();
            assert_eq!(round_tripped, packet, "{name}: {packet_path} does not round trip");
            receiver
                .apply_and_verify_transmission_packet(round_tripped)
                .unwrap_or_else(|error| panic!("{name}: could not apply {packet_path}: {error:?}"));
        }

        let replayed = receiver.into_dag().unwrap();
        assert_shape(&format!("{name} (replayed)"), &replayed, case);
        replayed.verify().unwrap();
    }
}

#[test]
fn spec_vector_batched_packets_replay() {
    let manifest = manifest();
    let mut split_cases = 0;
    for case in cases(&manifest) {
        let name = text(field(case, "name"));
        let batch_paths = paths(case, "batched_packets");
        if batch_paths.len() > 1 {
            split_cases += 1;
        }
        let mut receiver = BatchedDagReceiver::new();

        for batch_path in batch_paths {
            let committed = read_vector(&batch_path);
            let batch = BatchedTransmissionPacket::from_cbor(&committed)
                .unwrap_or_else(|error| panic!("{name}: {batch_path} does not decode: {error:?}"));

            let first = batch.to_cbor().unwrap();
            let second = batch.to_cbor().unwrap();
            assert_eq!(
                first, second,
                "{name}: encoding {batch_path} twice produced different bytes"
            );
            assert_eq!(
                first, committed,
                "{name}: re-encoded {batch_path} differs from the bytes Go committed"
            );

            let round_tripped = BatchedTransmissionPacket::from_cbor(&first).unwrap();
            assert_eq!(round_tripped, batch, "{name}: {batch_path} does not round trip");
            receiver
                .apply_and_verify(&round_tripped)
                .unwrap_or_else(|error| panic!("{name}: could not apply {batch_path}: {error:?}"));
        }

        let replayed = receiver.finish_verified().unwrap();
        assert_shape(&format!("{name} (batch replayed)"), &replayed, case);
    }

    // Without this, a corpus that happened to fit every case in one batch would
    // still pass, and the batch-splitting path -- where the interesting proof bugs
    // live -- would go untested while looking tested.
    assert!(
        split_cases > 0,
        "no case in the corpus splits across multiple batches; the batching path is untested"
    );
}

/// The eighth assertion, and with the ninth the newest here: for its first four
/// releases this corpus compared CBOR only.
///
/// That gap was not theoretical, and this crate is where it bit. The two formats
/// do not sort map keys by the same rule -- CBOR is length-first then bytewise
/// (RFC 8949 core-deterministic), while Go reaches JSON through `encoding/json`,
/// which sorts bytewise with no length term. `to_json` here reused the
/// CBOR-ordered wire tree, so every mixed-length map came out in the wrong order,
/// and all seven assertions above passed the whole time because none of them ever
/// opened a `.json` file.
///
/// Two things are checked per artifact, and the second is the load-bearing one:
///
/// 1. re-encoding the decoded value to JSON reproduces the committed JSON bytes;
/// 2. re-encoding that SAME value to CBOR reproduces the committed CBOR bytes.
///
/// (2) is what makes this more than a formatting test. It says the value this
/// port gets out of the JSON decoder is indistinguishable from the value it gets
/// out of the CBOR decoder -- the actual interoperability claim, and one that
/// cannot be proved by comparing a file against itself.
#[test]
fn spec_vector_json_matches_the_committed_bytes() {
    let manifest = manifest();
    let mut checked = 0;
    for case in cases(&manifest) {
        let name = text(field(case, "name"));
        let root_hash = text(field(case, "root_hash"));

        let mut dag_cbor = vec![text(field(case, "full_dag")).to_owned()];
        dag_cbor.extend(paths(case, "partial_dags"));
        let mut dag_json = vec![text(field(case, "full_dag_json")).to_owned()];
        dag_json.extend(paths(case, "partial_dags_json"));
        assert_eq!(
            dag_cbor.len(),
            dag_json.len(),
            "{name}: the manifest lists a different number of JSON and CBOR DAGs"
        );
        for (cbor_path, json_path) in dag_cbor.iter().zip(&dag_json) {
            let committed = read_vector(json_path);
            let dag = Dag::from_json(&committed)
                .unwrap_or_else(|error| panic!("{name}: {json_path} does not decode: {error:?}"));
            assert_eq!(dag.root().as_str(), root_hash, "{name}: {json_path} root");
            dag.verify()
                .unwrap_or_else(|error| panic!("{name}: {json_path} does not verify: {error:?}"));
            assert_json_and_cbor_agree(
                name,
                json_path,
                cbor_path,
                &committed,
                &dag.to_json().unwrap(),
                &dag.to_cbor().unwrap(),
            );
            checked += 1;
        }

        let packet_cbor = paths(case, "transmission_packets");
        let packet_json = paths(case, "transmission_packets_json");
        assert_eq!(
            packet_cbor.len(),
            packet_json.len(),
            "{name}: the manifest lists a different number of JSON and CBOR packets"
        );
        for (cbor_path, json_path) in packet_cbor.iter().zip(&packet_json) {
            let committed = read_vector(json_path);
            let packet = TransmissionPacket::from_json(&committed)
                .unwrap_or_else(|error| panic!("{name}: {json_path} does not decode: {error:?}"));
            assert_json_and_cbor_agree(
                name,
                json_path,
                cbor_path,
                &committed,
                &packet.to_json().unwrap(),
                &packet.to_cbor().unwrap(),
            );
            checked += 1;
        }

        let batch_cbor = paths(case, "batched_packets");
        let batch_json = paths(case, "batched_packets_json");
        assert_eq!(
            batch_cbor.len(),
            batch_json.len(),
            "{name}: the manifest lists a different number of JSON and CBOR batches"
        );
        for (cbor_path, json_path) in batch_cbor.iter().zip(&batch_json) {
            let committed = read_vector(json_path);
            let batch = BatchedTransmissionPacket::from_json(&committed)
                .unwrap_or_else(|error| panic!("{name}: {json_path} does not decode: {error:?}"));
            assert_json_and_cbor_agree(
                name,
                json_path,
                cbor_path,
                &committed,
                &batch.to_json().unwrap(),
                &batch.to_cbor().unwrap(),
            );
            checked += 1;
        }
    }
    assert!(
        checked > 0,
        "the manifest names no JSON artifacts; this assertion would pass vacuously"
    );
}

fn assert_json_and_cbor_agree(
    name: &str,
    json_path: &str,
    cbor_path: &str,
    committed_json: &[u8],
    re_json: &[u8],
    re_cbor: &[u8],
) {
    assert_eq!(
        re_json, committed_json,
        "{name}: re-encoded {json_path} differs from the JSON bytes Go committed"
    );
    let committed_cbor = read_vector(cbor_path);
    assert_eq!(
        re_cbor,
        committed_cbor.as_slice(),
        "{name}: {json_path} decoded from JSON re-encodes to different CBOR than {cbor_path}"
    );
}

/// The ninth assertion: the guard on the guard.
///
/// Map key order is only observable when the keys differ in LENGTH, and every map
/// in this corpus except one is keyed by CID -- and a CID is `b` plus base32 of
/// exactly 36 bytes, so it is exactly 59 characters, always. If
/// `json_metadata_probe` ever lost its mixed-length metadata, every assertion
/// above would keep passing while quietly losing the ability to fail for the
/// reason it exists. Reordering a map preserves its encoded byte LENGTH too, so a
/// size comparison would not have noticed either.
#[test]
fn spec_vector_probe_case_can_tell_the_two_sort_rules_apart() {
    let manifest = manifest();
    let probe = cases(&manifest)
        .iter()
        .find(|case| !items(field(case, "additional_data")).is_empty())
        .expect(
            "no case in the corpus carries additional data; nothing here can distinguish the JSON and CBOR key orders",
        );
    let name = text(field(probe, "name"));

    let mut lengths: Vec<usize> = items(field(probe, "additional_data"))
        .iter()
        .map(|entry| text(field(entry, "key")).len())
        .collect();
    lengths.sort_unstable();
    lengths.dedup();
    assert!(
        lengths.len() >= 2,
        "{name}: every metadata key is the same length, and the two sort rules agree on those"
    );

    // "aaa-probe" is 9 bytes and "zz-probe" is 8, so length-first and bytewise
    // MUST place them in opposite orders. Both are unambiguous as raw substrings
    // of either encoding: this fixture's leaf content is uppercase ASCII, and a
    // base32 CID contains no "-".
    let json = read_vector(text(field(probe, "full_dag_json")));
    let cbor = read_vector(text(field(probe, "full_dag")));
    assert!(
        find_bytes(&json, b"aaa-probe") < find_bytes(&json, b"zz-probe"),
        "{name}: the committed JSON sorted the 8-byte key first, which is CBOR's length-first rule"
    );
    assert!(
        find_bytes(&cbor, b"zz-probe") < find_bytes(&cbor, b"aaa-probe"),
        "{name}: the committed CBOR sorted the 9-byte key first, which is not RFC 8949 core-deterministic order"
    );
}
